tool_input.command:
mkdir -p $TMPDIR/scratch && cat > $TMPDIR/scratch/T.java << 'EOF'
import org.apache.commons.lang3.exception.ExceptionUtils;

public class T {
    public static void main(String[] args) {
        RuntimeException re = new RuntimeException("x");
        RuntimeException r = ExceptionUtils.throwUnchecked(re);
        System.out.println(r);
    }
}
EOF
javac -nowarn --release 8 -cp target/classes -d $TMPDIR/scratch $TMPDIR/scratch/T.java 2>&1 | head -50
